(window.__qhadithX=window.__qhadithX||{})[46]={"10":[{"c":"Sahih Bukhari","r":"Hadith 3812","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3812","x":"Narrated Sa`d bin Abi Waqqas:\n\nI have never heard the Prophet (ﷺ) saying about anybody walking on the earth that he is from the people of Paradise except `Abdullah bin Salam. The following Verse was revealed concerning him: \"And a witness from the children of Israel testifies that this Qur'an is true\" (46.10)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ سَمِعْتُ مَالِكًا، يُحَدِّثُ عَنْ أَبِي النَّضْرِ، مَوْلَى عُمَرَ بْنِ عُبَيْدِ اللَّهِ عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ، عَنْ أَبِيهِ، قَالَ مَا سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ لأَحَدٍ يَمْشِي عَلَى الأَرْضِ إِنَّهُ مِنْ أَهْلِ الْجَنَّةِ‏.‏ إِلاَّ لِعَبْدِ اللَّهِ بْنِ سَلاَمٍ قَالَ وَفِيهِ نَزَلَتْ هَذِهِ الآيَةُ ‏{‏وَشَهِدَ شَاهِدٌ مِنْ بَنِي إِسْرَائِيلَ‏}‏ الآيَةَ‏.‏ قَالَ لاَ أَدْرِي قَالَ مَالِكٌ الآيَةَ أَوْ فِي الْحَدِيثِ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3256","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3256","x":"Narrated 'Abdul-Malik bin 'Umair:\n\nfrom the nephew of 'Abdullah bin Salam who said: \"When they were after 'Uthman, 'Abdullah bin Salam came, and 'Uthman said to him: 'What did you come for?' He said: 'I came to assist you.' He said: 'Go to the people to repel their advances against me. For verily your going is better to me than your entering here.'\" He said: \"So 'Abdullah bin Salam went to the people and said: 'O you people! During Jahiliyyah I was named so-and-so, then the Messenger of Allah (ﷺ) named me 'Abdullah, and some Ayat from the Book of Allah were revealed about me. (The following) was revealed about me: 'A witness from among the Children of Isra'il has testified to something similar, and believed while you rejected. Verily, Allah does not guide the wrongdoing people. (46:10)\" And (the following) was revealed about me: 'Sufficient as a witness between me and you is Allah, and those too who have knowledge of the Scripture. (13:43)\" Allah has sheathed the sword from you and the angels are your neighbors in this city of yours, the one in which the Revelation came to your Prophet. But by Allah! (Fear) Allah regarding this man; if you kill him, then by Allah! If you kill him, then you will cause the angels to remove your goodness from you, and to raise Allah's sheathed sword against you, such that it will never be sheathed again until the Day of Resurrection.'\" He said: \"They said: 'Kill the Jew and kill 'Uthman.'\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ سَعِيدٍ الْكِنْدِيُّ، حَدَّثَنَا أَبُو مُحَيَّاةَ، عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، عَنِ ابْنِ أَخِي عَبْدِ اللَّهِ بْنِ سَلاَمٍ، لَمَّا أُرِيدَ عُثْمَانُ جَاءَ عَبْدُ اللَّهِ بْنُ سَلاَمٍ فَقَالَ لَهُ عُثْمَانُ مَا جَاءَ بِكَ قَالَ جِئْتُ فِي نَصْرِكَ قَالَ اخْرُجْ إِلَى النَّاسِ فَاطْرُدْهُمْ عَنِّي فَإِنَّكَ خَارِجٌ خَيْرٌ لِي مِنْكَ دَاخِلٌ ‏.‏ فَخَرَجَ عَبْدُ اللَّهِ إِلَى النَّاسِ فَقَالَ أَيُّهَا النَّاسُ إِنَّهُ كَانَ اسْمِي فِي الْجَاهِلِيَّةِ فُلاَنٌ فَسَمَّانِي رَسُولُ اللَّهِ صلى الله عليه وسلم عَبْدَ اللَّهِ وَنَزَلَ فِيَّ آيَاتٌ مِنْ كِتَابِ اللَّهِ نَزَلَتْ فِيَّ ‏:‏ ‏(‏ وشَهِدَ شَاهِدٌ مِنْ بَنِي إِسْرَائِيلَ عَلَى مِثْلِهِ فَآمَنَ وَاسْتَكْبَرْتُمْ إِنَّ اللَّهَ لاَ يَهْدِي الْقَوْمَ الظَّالِمِينَ ‏)‏ وَنَزَلَتْ فِيَّ ‏:‏ ‏(‏قلْ كَفَى بِاللَّهِ شَهِيدًا بَيْنِي وَبَيْنَكُمْ وَمَنْ عِنْدَهُ عِلْمُ الْكِتَابِ ‏)‏ إِنَّ لِلَّهِ سَيْفًا مَغْمُودًا عَنْكُمْ وَإِنَّ الْمَلاَئِكَةَ قَدْ جَاوَرَتْكُمْ فِي بَلَدِكُمْ هَذَا الَّذِي نَزَلَ فِيهِ نَبِيُّكُمْ فَاللَّهَ اللَّهَ فِي هَذَا الرَّجُلِ أَنْ تَقْتُلُوهُ فَوَاللَّهِ إِنْ قَتَلْتُمُوهُ لَتَطْرُدُنَّ جِيرَانَكُمُ الْمَلاَئِكَةَ وَلَتَسُلُّنَّ سَيْفَ اللَّهِ الْمَغْمُودَ عَنْكُمْ فَلاَ يُغْمَدُ إِلَى يَوْمِ الْقِيَامَةِ قَالَ فَقَالُوا اقْتُلُوا الْيَهُودِيَّ وَاقْتُلُوا عُثْمَانَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ ‏.‏ وَقَدْ رَوَاهُ شُعَيْبُ بْنُ صَفْوَانَ عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ عَنِ ابْنِ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ سَلاَمٍ عَنْ جَدِّهِ عَبْدِ اللَّهِ بْنِ سَلاَمٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 46, Hadith 3803","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-46/Hadith-3803","x":"Narrated 'Abdul-Malik bin 'Umair:\n\nfrom the nephew of 'Abdullah bin Salam who said: \"When they were about to kill 'Uthman, 'Abdullah bin Salam came and 'Uthman said to him: 'What did you come for?' He said: 'I came to assist you.' He said: 'Go to the people to repel their advances against me. For verily your going is better to me than your entering here.' So 'Abdullah went to the people and said: 'O you people! During Jahiliyyah I was named so-and-so, then the Messenger of Allah (ﷺ) named me 'Abdullah, and some Ayat from the Book of Allah were revealed about me. (The following) was revealed about me: \"A witness from among the Children of Isra'il has testified to something similar and believed while you rejected. Verily, Allah does not guide the wrongdoing people. (46:10)\" [And (the following) was revealed about me:] \"Sufficient as a witness between me and you is Allah, and those too who have knowledge of the Scripture. (13:43)\" Allah has sheathed the sword from you and the angels are your neighbors in this city of yours, the one in which the Revelation came to the Messenger of Allah (ﷺ). But by Allah! (Fear) Allah regarding this man; if you kill him, then by Allah! If you kill him, then you will cause the angels to remove your goodness from you, and to raise Allah's sheathed sword against you, such that it will never be sheathed again until the Day of Resurrection.'\" He said: \"They said: 'Kill the Jew and kill 'Uthman.'\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ سَعِيدٍ الْكِنْدِيُّ، قَالَ حَدَّثَنَا أَبُو مُحَيَّاةَ يَحْيَى بْنُ يَعْلَى بْنِ عَطَاءٍ عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، عَنِ ابْنِ أَخِي عَبْدِ اللَّهِ بْنِ سَلاَمٍ، قَالَ لَمَّا أُرِيدَ قَتْلُ عُثْمَانَ جَاءَ عَبْدُ اللَّهِ بْنُ سَلاَمٍ فَقَالَ لَهُ عُثْمَانُ مَا جَاءَ بِكَ قَالَ جِئْتُ فِي نَصْرِكَ ‏.‏ قَالَ اخْرُجْ إِلَى النَّاسِ فَاطْرُدْهُمْ عَنِّي فَإِنَّكَ خَارِجًا خَيْرٌ لِي مِنْكَ دَاخِلاً ‏.‏ فَخَرَجَ عَبْدُ اللَّهِ إِلَى النَّاسِ فَقَالَ أَيُّهَا النَّاسُ إِنَّهُ كَانَ اسْمِي فِي الْجَاهِلِيَّةِ فُلاَنٌ فَسَمَّانِي رَسُولُ اللَّهِ صلى الله عليه وسلم عَبْدَ اللَّهِ وَنَزَلَتْ فِيَّ آيَاتٌ مِنْ كِتَابِ اللَّهِ فَنَزَلَتْ فِيَّ ‏:‏ ‏(‏ وشهد شَاهِدٌ مِنْ بَنِي إِسْرَائِيلَ عَلَى مِثْلِهِ فَآمَنَ وَاسْتَكْبَرْتُمْ إِنَّ اللَّهَ لاَ يَهْدِي الْقَوْمَ الظَّالِمِينَ ‏)‏ وَنَزَلَتْ فِيَّ ‏:‏ ‏(‏ قلْ كَفَى بِاللَّهِ شَهِيدًا بَيْنِي وَبَيْنَكُمْ وَمَنْ عِنْدَهُ عِلْمُ الْكِتَابِ ‏)‏ إِنَّ لِلَّهِ سَيْفًا مَغْمُودًا عَنْكُمْ وَإِنَّ الْمَلاَئِكَةَ قَدْ جَاوَرَتْكُمْ فِي بَلَدِكُمْ هَذَا الَّذِي نَزَلَ فِيهِ رَسُولُ اللَّهِ صلى الله عليه وسلم فَاللَّهَ اللَّهَ فِي هَذَا الرَّجُلِ أَنْ تَقْتُلُوهُ فَوَاللَّهِ لَئِنْ قَتَلْتُمُوهُ لَتَطْرُدُنَّ جِيرَانَكُمُ الْمَلاَئِكَةَ وَلَتَسُلُّنَّ سَيْفَ اللَّهِ الْمَغْمُودَ عَنْكُمْ فَلاَ يُغْمَدُ عَنْكُمْ إِلَى يَوْمِ الْقِيَامَةِ ‏.‏ قَالُوا اقْتُلُوا الْيَهُودِيَّ وَاقْتُلُوا عُثْمَانَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ إِنَّمَا نَعْرِفُهُ مِنْ حَدِيثِ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏.‏ وَقَدْ رَوَى شُعَيْبُ بْنُ صَفْوَانَ هَذَا الْحَدِيثَ عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ فَقَالَ عَنْ عُمَرَ بْنِ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ سَلاَمٍ عَنْ جَدِّهِ عَبْدِ اللَّهِ بْنِ سَلاَمٍ ‏.‏","v":[]}],"15":[{"c":"Muwatta Malik","r":"Book 41, Hadith 1513","u":"https://quranx.com/Hadith/Malik/In-Book/Book-41/Hadith-1513","x":"Malik related to me that he had heard that Uthman ibn Affan was brought a woman who had given birth after six months and he ordered her to be stoned. Ali ibn Abi Talib said to him, \"She does not deserve that. Allah, the Blessed, the Exalted, says in His Book, 'Their carrying and weaning is thirty months,' (Sura 46 ayat 15) and he said, 'Mothers suckle their children for two full years for whoever wishes to complete the suckling.' (Sura 2 ayat 233) Pregnancy can then be six months, so she does not deserve to be stoned.\" Uthman ibn Affan sent for her and found that she had already been stoned. Malik related to me that he asked Ibn Shihab about someone who committed sodomy. Ibn Shihab said, \"He is to be stoned, whether or not he is muhsan.\"","ar":"وَحَدَّثَنِي مَالِكٌ، أَنَّهُ بَلَغَهُ أَنَّ عُثْمَانَ بْنَ عَفَّانَ، أُتِيَ بِامْرَأَةٍ قَدْ وَلَدَتْ فِي سِتَّةِ أَشْهُرٍ فَأَمَرَ بِهَا أَنْ تُرْجَمَ فَقَالَ عَلِيُّ بْنُ أَبِي طَالِبٍ لَيْسَ ذَلِكَ عَلَيْهَا إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَقُولُ فِي كِتَابِهِ ‏{‏وَحَمْلُهُ وَفِصَالُهُ ثَلاَثُونَ شَهْرًا‏}‏ وَقَالَ ‏{‏وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلاَدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَنْ يُتِمَّ الرَّضَاعَةَ‏}‏ فَالْحَمْلُ يَكُونُ سِتَّةَ أَشْهُرٍ فَلاَ رَجْمَ عَلَيْهَا ‏.‏ فَبَعَثَ عُثْمَانُ بْنُ عَفَّانَ فِي أَثَرِهَا فَوَجَدَهَا قَدْ رُجِمَتْ ‏.‏","v":[]}],"20":[{"c":"Muwatta Malik","r":"Book 49, Hadith 1710","u":"https://quranx.com/Hadith/Malik/In-Book/Book-49/Hadith-1710","x":"Yahya related to me from Malik from Yahya ibn Said that Umar ibn al-Khattab said, \"Beware of meat. It has addictiveness like the addictiveness of wine.\" Yahya related to me from Malik from Yahya ibn Said that Umar ibn al-Khattab saw Jabir ibn Abdullah carrying some meat. He said, \"What is this?\" He said, \"Amir al- muminin. We desired meat and I bought some meat for a dirham.\" Umar said, \"Does one of you want to fill his belly apart from his neighbour or nephew? How can you overlook this ayat? 'You squandered your good things in the life of this world and sought comfort in them.' \" (Sura 46 ayat 20).","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ يَحْيَى بْنِ سَعِيدٍ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ، أَدْرَكَ جَابِرَ بْنَ عَبْدِ اللَّهِ وَمَعَهُ حِمَالُ لَحْمٍ فَقَالَ مَا هَذَا فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ قَرِمْنَا إِلَى اللَّحْمِ فَاشْتَرَيْتُ بِدِرْهَمٍ لَحْمًا ‏.‏ فَقَالَ عُمَرُ أَمَا يُرِيدُ أَحَدُكُمْ أَنْ يَطْوِيَ بَطْنَهُ عَنْ جَارِهِ أَوِ ابْنِ عَمِّهِ أَيْنَ تَذْهَبُ عَنْكُمْ هَذِهِ الآيَةُ ‏{‏أَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا وَاسْتَمْتَعْتُمْ بِهَا ‏}‏","v":[]}],"24":[{"c":"Al-Adab Al-Mufrad","r":"Book 39, Hadith 908","u":"https://quranx.com/Hadith/Adab/English/Book-39/Hadith-908","x":"'A'isha said, \"When the Prophet, may Allah bless him and grant him peace, saw a cloud in the sky, he would get up and down and walk to and fro, and his face would change colour. When it rained, that would leave him.\" When A'isha commented on that, the Prophet, may Allah bless him and grant him peace, said, \"I do not know. Perhaps it will be as Allah Almighty says:\n\n'When they saw it as a storm cloud advancing on their valleys...' (46:24)\"","ar":"حَدَّثَنَا مَكِّيُّ بْنُ إِبْرَاهِيمَ، قَالَ‏:‏ أَخْبَرَنَا ابْنُ جُرَيْجٍ، عَنْ عَطَاءٍ، عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ‏:‏ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا رَأَى مَخِيلَةً دَخَلَ وَخَرَجَ، وَأَقْبَلَ وَأَدْبَرَ، وَتَغَيَّرَ وَجْهُهُ، فَإِذَا مَطَرَتِ السَّمَاءُ سُرِّيَ، فَعَرَّفَتْهُ عَائِشَةُ ذَلِكَ، فَقَالَ النَّبِيُّ صلى الله عليه وسلم‏:‏ وَمَا أَدْرِي لَعَلَّهُ كَمَا قَالَ اللَّهُ عَزَّ وَجَلَّ‏:‏ ‏{‏فَلَمَّا رَأَوْهُ عَارِضًا مُسْتَقْبِلَ أَوْدِيَتِهِمْ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3206","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3206","x":"Narrated Ata:\n\n`Aisha said If the Prophet (ﷺ) saw a cloud In the sky, he would walk to and fro in agitation, go out and come in, and the color of his face would change, and if it rained, he would feel relaxed.\" So `Aisha knew that state of his. So the Prophet (ﷺ) said, I don't know (am afraid), it may be similar to what happened to some people referred to in the Holy Qur'an in the following Verse: -- \"Then when they saw it as a dense cloud coming towards their valleys, they said, 'This is a cloud bringing us rain!' Nay, but, it is that (torment) which you were asking to be hastened a wind wherein is severe torment.\" (46.24)","ar":"حَدَّثَنَا مَكِّيُّ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا ابْنُ جُرَيْجٍ، عَنْ عَطَاءٍ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا رَأَى مَخِيلَةً فِي السَّمَاءِ أَقْبَلَ وَأَدْبَرَ وَدَخَلَ وَخَرَجَ وَتَغَيَّرَ وَجْهُهُ، فَإِذَا أَمْطَرَتِ السَّمَاءُ سُرِّيَ عَنْهُ، فَعَرَّفَتْهُ عَائِشَةُ ذَلِكَ، فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ مَا أَدْرِي لَعَلَّهُ كَمَا قَالَ قَوْمٌ ‏{‏فَلَمَّا رَأَوْهُ عَارِضًا مُسْتَقْبِلَ أَوْدِيَتِهِمْ‏}‏ ‏\"‏‏.‏ الآيَةَ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 5, Book 34, Hadith 3891","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-34/Hadith-3891","x":"It was narrated that ‘Aishah said:\n\n\"If the Messenger of Allah (ﷺ) saw a cloud that looked as if it was bringing rain, the color of his face would change, and he would go in and out and walk to and fro. Then, if it rained, he would feel relieved.\" ‘Aishah mentioned to him what she had seen him do, and he said: \"How do you know? Perhaps it would be as the people of Hud said: ‘Then, when they saw it as a dense cloud coming towards their valleys, they said: \"This is a cloud bringing us rain!\" Nay, but it is that (torment) which you were asking to be hastened.\" [46:24]","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا مُعَاذُ بْنُ مُعَاذٍ، عَنِ ابْنِ جُرَيْجٍ، عَنْ عَطَاءٍ، عَنْ عَائِشَةَ، قَالَتْ كَانَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ إِذَا رَأَى مَخِيلَةً تَلَوَّنَ وَجْهُهُ وَتَغَيَّرَ وَدَخَلَ وَخَرَجَ وَأَقْبَلَ وَأَدْبَرَ فَإِذَا أَمْطَرَتْ سُرِّيَ عَنْهُ ‏.‏ قَالَ فَذَكَرَتْ لَهُ عَائِشَةُ بَعْضَ مَا رَأَتْ مِنْهُ فَقَالَ ‏\"‏ وَمَا يُدْرِيكِ لَعَلَّهُ كَمَا قَالَ قَوْمُ هُودٍ ‏{فَلَمَّا رَأَوْهُ عَارِضًا مُسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا هَذَا عَارِضٌ مُمْطِرُنَا بَلْ هُوَ مَا اسْتَعْجَلْتُمْ بِهِ }‏ ‏\"‏ ‏.‏ الآيَةَ","v":[]},{"c":"Sahih Muslim","r":"Hadith 899b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-899b","x":"'Ata' b. Rabah reported on the authority of 'A'isha, the wife of the Messenger of Allah (way peace be upon him), who said:\n\nWhenever the wind was stormy, the Messenger of Allah (ﷺ) used to say: O Allah! I ask Thee for what is good in it, and the good which it contains, and the good of that which it was sent for. I seek refuge with Thee from what is evil in it, what evil it contains, and the evil of that what it was sent for; and when there was a thunder and lightning in the sky, his colour underwent a change, and he went out and in, backwards and forwards; and when the rain came, he felt relieved, and I noticed that (the sign of relief) on his face. 'A'isha asked him (about it) and he said: It may be as the people of 'Ad said: When they saw a cloud formation coming to their valley they said:\" It is a cloud which would give us rain\" (Qur'an, xlvi. 24).","ar":"وَحَدَّثَنِي أَبُو الطَّاهِرِ، أَخْبَرَنَا ابْنُ وَهْبٍ، قَالَ سَمِعْتُ ابْنَ جُرَيْجٍ، يُحَدِّثُنَا عَنْ عَطَاءِ، بْنِ أَبِي رَبَاحٍ عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صلى الله عليه وسلم أَنَّهَا قَالَتْ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا عَصَفَتِ الرِّيحُ قَالَ ‏\"‏ اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيهَا وَخَيْرَ مَا أُرْسِلَتْ بِهِ وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا وَشَرِّ مَا أُرْسِلَتْ بِهِ ‏\"‏ ‏.‏ قَالَتْ وَإِذَا تَخَيَّلَتِ السَّمَاءُ تَغَيَّرَ لَوْنُهُ وَخَرَجَ وَدَخَلَ وَأَقْبَلَ وَأَدْبَرَ فَإِذَا مَطَرَتْ سُرِّيَ عَنْهُ فَعَرَفْتُ ذَلِكَ فِي وَجْهِهِ ‏.‏ قَالَتْ عَائِشَةُ فَسَأَلْتُهُ فَقَالَ ‏\"‏ لَعَلَّهُ يَا عَائِشَةُ كَمَا قَالَ قَوْمُ عَادٍ ‏{‏ فَلَمَّا رَأَوْهُ عَارِضًا مُسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا هَذَا عَارِضٌ مُمْطِرُنَا‏}‏ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 899c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-899c","x":"'A'isha, the wife of the Messenger of Allah (ﷺ), reported:\n\nI never saw Allah's Messenger (ﷺ) laugh to such an extent that I could see his uvula-whereas he used to smile only-and when he saw dark clouds or wind, (the signs of fear) were depicted on his face. I said: Messenger of Allah, I find people being happy when they ace the dark cloud in the hope that it would bring rain, but I find that when you see that (the cloud) there is an anxiety on your face. He said: 'A'isha, I am afraid that there may be a calamity in it, for a people was afflicted with wind, when the people saw the calamity they said:\" It is a cloud which would give us rain\" (Qur'an. xlvi. 24).","ar":"وَحَدَّثَنِي هَارُونُ بْنُ مَعْرُوفٍ، حَدَّثَنَا ابْنُ وَهْبٍ، عَنْ عَمْرِو بْنِ الْحَارِثِ، ح وَحَدَّثَنِي أَبُو الطَّاهِرِ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، أَخْبَرَنَا عَمْرُو بْنُ الْحَارِثِ، أَنَّ أَبَا النَّضْرِ، حَدَّثَهُ عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صلى الله عليه وسلم أَنَّهَا قَالَتْ مَا رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم مُسْتَجْمِعًا ضَاحِكًا حَتَّى أَرَى مِنْهُ لَهَوَاتِهِ إِنَّمَا كَانَ يَتَبَسَّمُ - قَالَتْ- وَكَانَ إِذَا رَأَى غَيْمًا أَوْ رِيحًا عُرِفَ ذَلِكَ فِي وَجْهِهِ ‏.‏ فَقَالَتْ يَا رَسُولَ اللَّهِ أَرَى النَّاسَ","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3257","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3257","x":"Narrated 'Aishah [may Allah be pleased with her]:\n\n\"When the Prophet (ﷺ) saw storm clouds he would pace back and forth. And when it rained, he would relax.\" She said: \"I said something to him about that, and he said: 'What do I know? Maybe it is as Allah, Most High said: Then, when they saw it as a dense cloud approaching their valleys, they said: \"This is a cloud bringing us rain (46:24).\"'","ar":"حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ الأَسْوَدِ أَبُو عَمْرٍو الْبَصْرِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ رَبِيعَةَ، عَنِ ابْنِ جُرَيْجٍ، عَنْ عَطَاءٍ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا رَأَى مَخِيلَةً أَقْبَلَ وَأَدْبَرَ فَإِذَا مَطَرَتْ سُرِّيَ عَنْهُ ‏.‏ قَالَتْ فَقُلْتُ لَهُ ‏.‏ فَقَالَ ‏\"‏ وَمَا أَدْرِي لَعَلَّهُ كَمَا قَالَ اللَّهُ تَعَالَى ‏:‏ ‏(‏فلمَّا رَأَوْهُ عَارِضًا مُسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا هَذَا عَارِضٌ مُمْطِرُنَا ‏)‏ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ ‏.‏","v":[]}]};